$ErrorActionPreference = "Stop"
Set-StrictMode -Version Latest

Write-Host ""
Write-Host "=============================================" -ForegroundColor Cyan
Write-Host " SaborFlow - Etapa 13.6" -ForegroundColor Cyan
Write-Host " Sessoes, dispositivos e revogacao" -ForegroundColor Cyan
Write-Host "=============================================" -ForegroundColor Cyan
Write-Host ""

if (-not (Test-Path ".\package.json")) {
    throw "Execute este instalador na pasta raiz do projeto SaborFlow."
}

if (-not (Test-Path ".\database\migrations\031_admin_password_lockout.sql")) {
    throw "Migration 031 nao encontrada. A Etapa 13.5 precisa estar presente."
}

if (-not (Select-String -Path ".\lib\auth.ts" -Pattern 'return `v3.${encoded}.${sign(encoded)}`' -SimpleMatch -Quiet)) {
    throw "lib\auth.ts esta em uma versao diferente da esperada. Nada foi alterado."
}

if (-not (Select-String -Path ".\components\admin\security-panel.tsx" -Pattern "Autenticação em duas etapas" -SimpleMatch -Quiet)) {
    throw "security-panel.tsx esta em uma versao diferente da esperada. Nada foi alterado."
}

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backupRoot = Join-Path $env:TEMP "SaborFlow-Etapa13-6-Backup-$timestamp"
New-Item -ItemType Directory -Force -Path $backupRoot | Out-Null

$targets = @(
    "lib\auth.ts"
    "lib\tenant-access.ts"
    "lib\superadmin-auth.ts"
    "lib\security\admin-sessions.ts"
    "app\api\auth\logout\route.ts"
    "app\api\auth\2fa\verify\route.ts"
    "app\api\auth\passkey\verify\route.ts"
    "app\api\admin\sessions\route.ts"
    "proxy.ts"
    "components\admin\security-panel.tsx"
    "database\migrations\032_admin_sessions_devices.sql"
)

foreach ($target in $targets) {
    if (Test-Path $target) {
        $dest = Join-Path $backupRoot $target
        $destDir = Split-Path -Parent $dest
        if ($destDir) {
            New-Item -ItemType Directory -Force -Path $destDir | Out-Null
        }
        Copy-Item -LiteralPath $target -Destination $dest -Force
    }
}

$utf8NoBom = New-Object System.Text.UTF8Encoding($false)

function Write-Utf8Base64File {
    param(
        [Parameter(Mandatory = $true)][string]$Path,
        [Parameter(Mandatory = $true)][string]$Base64
    )

    $directory = Split-Path -Parent $Path
    if ($directory) {
        New-Item -ItemType Directory -Force -Path $directory | Out-Null
    }

    $bytes = [System.Convert]::FromBase64String($Base64)
    $content = [System.Text.Encoding]::UTF8.GetString($bytes)
    $fullPath = [System.IO.Path]::GetFullPath((Join-Path (Get-Location) $Path))
    [System.IO.File]::WriteAllText($fullPath, $content, $utf8NoBom)
    Write-Host "Gravado: $Path" -ForegroundColor Green
}

Write-Utf8Base64File -Path "lib\auth.ts" -Base64 ""
Write-Utf8Base64File -Path "lib\tenant-access.ts" -Base64 ""
Write-Utf8Base64File -Path "lib\superadmin-auth.ts" -Base64 ""
Write-Utf8Base64File -Path "lib\security\admin-sessions.ts" -Base64 ""
Write-Utf8Base64File -Path "app\api\auth\logout\route.ts" -Base64 ""
Write-Utf8Base64File -Path "app\api\auth\2fa\verify\route.ts" -Base64 ""
Write-Utf8Base64File -Path "app\api\auth\passkey\verify\route.ts" -Base64 ""
Write-Utf8Base64File -Path "app\api\admin\sessions\route.ts" -Base64 ""
Write-Utf8Base64File -Path "proxy.ts" -Base64 ""
Write-Utf8Base64File -Path "components\admin\security-panel.tsx" -Base64 ""
Write-Utf8Base64File -Path "database\migrations\032_admin_sessions_devices.sql" -Base64 ""

Write-Host ""
Write-Host "Verificando Git..." -ForegroundColor Cyan
git diff --check
if ($LASTEXITCODE -ne 0) {
    throw "git diff --check encontrou um problema. Backup: $backupRoot"
}

Write-Host ""
Write-Host "ETAPA 13.6 APLICADA LOCALMENTE." -ForegroundColor Green
Write-Host ""
Write-Host "Incluido:" -ForegroundColor Cyan
Write-Host " - sessoes persistentes por dispositivo no PostgreSQL"
Write-Host " - sessionId individual e revogavel em cada login"
Write-Host " - expiracao real apos 10 dias sem atividade"
Write-Host " - renovacao deslizante da sessao enquanto houver atividade valida"
Write-Host " - validacao conjunta com session_version"
Write-Host " - revogacao no logout"
Write-Host " - lista de dispositivos/sessoes no painel de seguranca"
Write-Host " - botao para encerrar uma sessao especifica"
Write-Host " - botao para encerrar todas as outras sessoes"
Write-Host " - sessao Superadmin vinculada a mesma sessao CPF"
Write-Host " - limite de 20 sessoes ativas por usuario"
Write-Host " - IP e User-Agent armazenados somente como hash"
Write-Host ""
Write-Host "ATENCAO:" -ForegroundColor Yellow
Write-Host " - a Migration 032 foi apenas CRIADA; NAO foi executada"
Write-Host " - nenhum commit foi feito"
Write-Host " - nenhum deploy foi feito"
Write-Host " - apos o futuro deploy, sessoes antigas v2/v3 serao invalidadas uma unica vez"
Write-Host "   e os usuarios precisarao entrar novamente para receber a sessao v4 gerenciavel"
Write-Host ""
Write-Host "Backup: $backupRoot" -ForegroundColor DarkGray
Write-Host ""
git status --short
